import {EFFECT_CSS} from './effects.js';
import {fileName} from './model.js';
import {createViewer} from './viewer.js';
export function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
export function savePNG(front,state){return new Promise((resolve,reject)=>front.toBlob(blob=>{if(!blob){reject(new Error('이미지 저장에 실패했어요. 다시 시도해주세요.'));return}download(blob,fileName(state)+'_카드.png');resolve()},'image/png'))}
export function saveHTML(front,back,state){
 const title=fileName(state).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 const css=`:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;min-height:100svh;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:system-ui,sans-serif;color:#c7c9d3;background:radial-gradient(ellipse,#202939,#090c13 70%)}h1{font-size:13px;letter-spacing:3px;font-weight:400;color:#e1d2b7;margin:0 0 25px}.stage{perspective:1400px;display:flex;align-items:center;justify-content:center;height:calc(var(--h) + 30px);--h:min(70svh,110vw,780px)}.card{height:var(--h);aspect-ratio:2/3;position:relative;transform-style:preserve-3d;touch-action:none;cursor:grab;outline:none;--power:${state.holo/100};--px:35%;--py:40%;--angle:125deg}.card:focus-visible{outline:2px solid #dec8a4;outline-offset:8px}.face{position:absolute;inset:0;border-radius:12px;overflow:hidden;backface-visibility:hidden;box-shadow:0 0 0 1px #e6d5b366,0 20px 70px #0009}.front{transform:translateZ(1px)}.back{transform:rotateY(180deg) translateZ(1px)}img{width:100%;height:100%;display:block;pointer-events:none;user-select:none}.foil,.glare,.sparkle{position:absolute;inset:0;pointer-events:none}.foil{background:repeating-linear-gradient(var(--angle),#80ffe3,#7db3ff 12%,#c2a1ff 24%,#ffaed4 36%,#fff6bb 48%,#80ffe3 60%);background-size:290% 290%;background-position:var(--px) var(--py);mix-blend-mode:color-dodge;opacity:calc(var(--power)*.32);mask-image:linear-gradient(115deg,#0009,#0001 35%,#000c 65%,#0003)}.glare{background:radial-gradient(ellipse at var(--px) var(--py),#fff8,#e6f3ff23 20%,transparent 60%);mix-blend-mode:screen;opacity:var(--power)}.sparkle{background-image:radial-gradient(#dffaffcc .55px,transparent 1px);background-size:4px 4px;mix-blend-mode:screen;opacity:${state.sparkle?state.holo/100*.22:0};mask-image:radial-gradient(ellipse at var(--px) var(--py),black,transparent 60%)}nav{display:flex;gap:8px;margin-top:20px}button{border:1px solid #ffffff26;background:#ffffff07;color:#ded3c0;border-radius:25px;padding:10px 17px;font:11px system-ui;cursor:pointer}button[aria-pressed=true]{background:#dec8a427}p{font-size:10px;color:#787e8c;margin:18px 0}footer{font-size:8px;letter-spacing:3px;color:#4e5664;margin-top:12px}.holo{display:flex;align-items:center;gap:12px;margin-top:18px;font-size:11px;color:#b6a892}.holo input{width:130px;accent-color:#dec8a4}.holo output{width:35px}nav{flex-wrap:wrap;justify-content:center}`;
 const html=`<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} · 홀로그램 카드</title><style>${css}${EFFECT_CSS}</style></head><body><h1>${title}</h1><div class="stage"><div class="card" id="card" data-effect="${state.effect||'holo'}" tabindex="0" role="img" aria-label="드래그 또는 방향키로 회전하는 캐릭터 카드"><div class="face front"><img src="${front.toDataURL('image/png')}" alt="카드 앞면"><div class="foil"></div><div class="glare"></div><div class="sparkle" style="display:${state.sparkle?'block':'none'}"></div></div><div class="face back"><img src="${back.toDataURL('image/png')}" alt="카드 뒷면"><div class="foil"></div><div class="glare"></div><div class="sparkle" style="display:${state.sparkle?'block':'none'}"></div></div></div></div><nav><button id="auto" aria-pressed="false">↻ 자동 회전</button><button id="flip">◇ 뒤집기</button><button id="reset">⟲ 정면으로</button></nav><label class="holo" for="holo">효과 강도 <input id="holo" type="range" min="0" max="100" step="1" value="${state.holo}"><output id="holoValue">${state.holo}%</output></label><p>드래그 · 방향키로 회전 / Home 키로 정면</p><footer>MADE WITH HOLO ATELIER</footer><script>const viewer=(${createViewer.toString()})(document.querySelector('#card'),{onAuto(value){document.querySelector('#auto').setAttribute('aria-pressed',String(value))}});document.querySelector('#auto').onclick=()=>viewer.toggleAuto();document.querySelector('#flip').onclick=()=>viewer.flip();document.querySelector('#reset').onclick=()=>viewer.reset();document.querySelector('#holo').oninput=e=>{const value=Number(e.target.value);document.querySelector('#card').style.setProperty('--power',value/100);document.querySelector('#holoValue').textContent=value+'%';document.querySelector('.sparkle').style.opacity=${state.sparkle?'value/100*.22':'0'};};<\/script></body></html>`;
 download(new Blob([html],{type:'text/html;charset=utf-8'}),fileName(state)+'_홀로그램.html');
}
